INSERT IGNORE INTO `custom_spec_info` (`class_mask`, `tab`, `role`, `description`) VALUES
(1, 1, 'DAMAGER', 'Закаленный в боях мастер оружия, который сокрушает противников мобильностью и мощными атаками.\nПредпочитаемое оружие: двуручные топоры, булавы, мечи\nОсновная характеристика: сила'),
(1, 2, 'DAMAGER', 'Неистовый берсерк с оружием в обеих руках, обрушивающий на врагов шквал ударов.\nПредпочитаемое оружие: двуручные топоры, булавы, мечи (по одному в каждой руке)\nОсновная характеристика: сила'),
(1, 3, 'TANK', 'Стойкий защитник, прикрывающий щитом себя и союзников.\nПредпочитаемое оружие: топор, булава, меч и щит\nОсновная характеристика: сила'),
(2, 1, 'HEALER', 'Взывает к силе Света, чтобы исцелять и защищать союзников и изгонять зло из самых темных уголков мира.\nПредпочитаемое оружие: меч, булава и щит\nОсновная характеристика: интеллект'),
(2, 2, 'TANK', 'Использует магию Света, чтобы защищать себя и союзников от нападающих.\nПредпочитаемое оружие: меч, булава, топор и щит\nОсновная характеристика: сила'),
(2, 3, 'DAMAGER', 'Праведный воитель, карающий врагов оружием и магией Света.\nПредпочитаемое оружие: двуручные мечи, булавы, топоры\nОсновная характеристика: сила'),
(4, 1, 'DAMAGER', 'Повелитель дикой природы, приручающий самых разных зверей, которые сражаются вместе с $Gним:ней;.\nПредпочитаемое оружие: луки, арбалеты, ружья\nОсновная характеристика: ловкость'),
(4, 2, 'DAMAGER', 'Меткий стрелок, поражающий врагов с большого расстояния.\nПредпочитаемое оружие: луки, арбалеты, ружья\nОсновная характеристика: ловкость'),
(4, 3, 'DAMAGER', 'Опытный следопыт, для которого яды зверей, взрывчатка и ловушки - смертоносное оружие.\nПредпочитаемое оружие: луки, арбалеты, ружья\nОсновная характеристика: ловкость'),
(8, 1, 'DAMAGER', 'Смертоносный мастер ядов, расправляющийся с жертвами при помощи отравленных кинжалов.\nПредпочитаемое оружие: кинжалы\nОсновная характеристика: ловкость'),
(8, 2, 'DAMAGER', 'Безжалостный боец, полагающийся на ловкость и хитрость в схватке лицом к лицу.\nПредпочитаемое оружие: мечи, топоры, булавы, кистевое оружие\nОсновная характеристика: ловкость'),
(8, 3, 'DAMAGER', 'Мастер теней, нападающий на ничего не подозревающую жертву из засады.\nПредпочитаемое оружие: кинжалы\nОсновная характеристика: ловкость'),
(16, 1, 'HEALER', 'Защищает союзников от урона магическими щитами и исцеляет их раны.\nПредпочитаемое оружие: посохи, жезлы, кинжалы, булавы\nОсновная характеристика: интеллект'),
(16, 2, 'HEALER', 'Универсальный лекарь, исцеляющий как отдельных союзников, так и целые группы, - даже из-за грани смерти.\nПредпочитаемое оружие: посохи, жезлы, кинжалы, булавы\nОсновная характеристика: интеллект'),
(16, 3, 'DAMAGER', 'Истребляет врагов зловещей магией Тьмы и заклинаниями периодического урона.\nПредпочитаемое оружие: посохи, жезлы, кинжалы, булавы\nОсновная характеристика: интеллект'),
(32, 1, 'TANK', 'Темный страж, подчиняющий себе жизненную энергию, чтобы выстоять под натиском врагов.\nПредпочитаемое оружие: двуручные топоры, булавы, мечи\nОсновная характеристика: сила'),
(32, 2, 'DAMAGER', 'Ледяной вестник гибели, направляющий силу рун и наносящий стремительные удары оружием.\nПредпочитаемое оружие: топоры, булавы, мечи в обеих руках\nОсновная характеристика: сила'),
(32, 3, 'DAMAGER', 'Повелитель смерти и тлена, распространяющий заразу и повелевающий нежитью.\nПредпочитаемое оружие: двуручные топоры, булавы, мечи\nОсновная характеристика: сила'),
(64, 1, 'DAMAGER', 'Заклинатель, обуздавший разрушительные силы природы и стихий.\nПредпочитаемое оружие: булава, кинжал и щит\nОсновная характеристика: интеллект'),
(64, 2, 'DAMAGER', 'Воин тотемов, разящий врагов оружием, наделенным силой стихий.\nПредпочитаемое оружие: топоры, булавы, кистевое оружие в обеих руках\nОсновная характеристика: ловкость'),
(64, 3, 'HEALER', 'Целитель, призывающий духов предков и очищающую силу воды, чтобы залечивать раны союзников.\nПредпочитаемое оружие: булава, кинжал и щит\nОсновная характеристика: интеллект'),
(128, 1, 'DAMAGER', 'Повелевает чистой тайной магией, уничтожая врагов сокрушительной силой.\nПредпочитаемое оружие: посох, жезл, кинжал, меч\nОсновная характеристика: интеллект'),
(128, 2, 'DAMAGER', 'Обращает против врагов чистую сущность огня, испепеляя их пламенем.\nПредпочитаемое оружие: посох, жезл, кинжал, меч\nОсновная характеристика: интеллект'),
(128, 3, 'DAMAGER', 'Сковывает врагов на месте и разбивает их магией льда.\nПредпочитаемое оружие: посох, жезл, кинжал, меч\nОсновная характеристика: интеллект'),
(256, 1, 'DAMAGER', 'Мастер темной магии, специализирующийся на заклинаниях похищения и периодического урона.\nПредпочитаемое оружие: посох, жезл, кинжал, меч\nОсновная характеристика: интеллект'),
(256, 2, 'DAMAGER', 'Повелитель демонов, обращающий души своих слуг в разрушительную силу.\nПредпочитаемое оружие: посох, жезл, кинжал, меч\nОсновная характеристика: интеллект'),
(256, 3, 'DAMAGER', 'Мастер хаоса, обрушивающий на врагов всепожирающее пламя.\nПредпочитаемое оружие: посох, жезл, кинжал, меч\nОсновная характеристика: интеллект'),
(1024, 1, 'DAMAGER', 'Принимает облик могучего лунного совуха и уничтожает врагов, сочетая тайную магию и магию природы.\nПредпочитаемое оружие: посох, кинжал, булава\nОсновная характеристика: интеллект'),
(1024, 2, 'DAMAGER', 'Принимает облик большой кошки, терзая врагов кровотечениями и укусами, или облик медведя, защищая союзников.\nПредпочитаемое оружие: посох, древковое оружие\nОсновная характеристика: ловкость'),
(1024, 3, 'HEALER', 'Повелевает могучей магией природы, исцеляя и восстанавливая силы союзников.\nПредпочитаемое оружие: посох, кинжал, булава\nОсновная характеристика: интеллект');
